        flashcards: [{ front: '4Rs of sustainability?', back: 'Reduce Reuse Recycle Refuse', hint: 'Waste minimization.' }, { front: 'Fundamental duties in which article?', back: 'Article 51A', hint: 'Constitution of India.' }],
        mnemonics: [{ phrase: 'RRRR', expansion: 'Reduce Reuse Recycle Refuse', meaning: 'Sustainability framework.' }]
